gate='/tmp/hive-mind-disk-baseline-4640c2e1-e8d6-4cab-ba60-93742c563fda'; i=0; echo "[hive-mind] start-gate: waiting up to 30s at $(date -u +%H:%M:%S) for the parent to release $gate" >&2; while [ ! -e "$gate" ] && [ "$i" -lt 300 ]; do i=$((i+1)); if [ $((i % 50)) -eq 0 ]; then echo "[hive-mind] start-gate: still waiting after $((i / 10))s at $(date -u +%H:%M:%S)" >&2; fi; sleep 0.1; done; if [ -e "$gate" ]; then echo "[hive-mind] start-gate: released after $((i / 10))s at $(date -u +%H:%M:%S)" >&2; else echo "[hive-mind] start-gate: not released within 30s; starting the task anyway at $(date -u +%H:%M:%S)" >&2; fi; rm -f "$gate"; echo "[hive-mind] start-gate: starting task command at $(date -u +%H:%M:%S)" >&2; exec echo WORKLOAD_STARTED; sleep 300
